INSERT INTO `la_tenant_system_menu` (`tenant_id`,`pid`,`type`,`name`,`icon`,`sort`,`perms`,`paths`,`component`,`selected`,`params`,`is_cache`,`is_show`,`is_disable`,`app_code`,`source`,`source_menu_key`,`is_core`,`create_time`,`update_time`) SELECT t.tenant_id,(SELECT p.id FROM `la_tenant_system_menu` p WHERE p.app_code='aigc_motion_sync' AND p.tenant_id=t.tenant_id AND p.source_menu_key='aigc_motion_sync_case' LIMIT 1),'A','设为内置模板','',0,'app.aigc_motion_sync.case/builtin','','','','',0,1,0,'aigc_motion_sync','app','aigc_motion_sync_case_builtin',0,UNIX_TIMESTAMP(),UNIX_TIMESTAMP() FROM (SELECT 0 AS tenant_id UNION SELECT id FROM `la_tenant` WHERE tactics<>1) t WHERE (SELECT p.id FROM `la_tenant_system_menu` p WHERE p.app_code='aigc_motion_sync' AND p.tenant_id=t.tenant_id AND p.source_menu_key='aigc_motion_sync_case' LIMIT 1) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `la_tenant_system_menu` m WHERE m.app_code='aigc_motion_sync' AND m.tenant_id=t.tenant_id AND m.source_menu_key='aigc_motion_sync_case_builtin');
